export const scriptSrc = "\n/* ============================================================\n   API (real backend \u2014 every write here is authorized server-side\n   by requireAuth + requireAdmin; a non-admin session gets 403)\n   ============================================================ */\n// Relative path: works out of the box when this file is served from the same\n// Vercel deployment as /api (the default for this project's vercel.json).\nconst API_BASE = window.SWIFTCART_API_BASE || \"/api\";\n\nasync function apiFetch(path, options = {}) {\n  const res = await fetch(`${API_BASE}${path}`, {\n    credentials: \"include\",\n    headers: { \"Content-Type\": \"application/json\", ...(options.headers || {}) },\n    ...options,\n    body: options.body ? JSON.stringify(options.body) : undefined,\n  });\n  let data = null;\n  try { data = await res.json(); } catch (e) { /* empty body */ }\n  if (!res.ok) {\n    const err = new Error((data && data.error) || `Request failed (${res.status})`);\n    err.status = res.status;\n    throw err;\n  }\n  return data;\n}\n\n// UI display labels <-> backend orderStatus enum. The admin screens were built around\n// the display labels below, so we translate at the API boundary rather than rewrite\n// every render function's string comparisons.\nconst STATUS_TO_API = { \"Placed\": \"placed\", \"Packing\": \"packing\", \"Out for delivery\": \"out_for_delivery\", \"Delivered\": \"delivered\", \"Cancelled\": \"cancelled\" };\nconst STATUS_FROM_API = { placed: \"Placed\", packing: \"Packing\", out_for_delivery: \"Out for delivery\", delivered: \"Delivered\", cancelled: \"Cancelled\" };\nconst PAY_METHOD_FROM_API = { cod: \"COD\", upi: \"UPI\", card: \"Card\", wallet: \"Wallet\" };\n\nfunction mapOrderFromApi(o) {\n  return {\n    id: o._id, // Mongo ObjectId string \u2014 every place that used to do Number(o.id) has been updated\n    customer: o.user ? o.user.name : \"Deleted customer\",\n    customerEmail: o.user ? o.user.email : \"\",\n    items: o.itemCount,\n    total: o.total,\n    status: STATUS_FROM_API[o.orderStatus] || o.orderStatus,\n    payment: PAY_METHOD_FROM_API[o.paymentMethod] || o.paymentMethod,\n    paid: o.paymentStatus === \"paid\",\n    riderId: null, // no rider-assignment backend yet \u2014 see note in renderRiders()\n    etaMin: null,\n    placed: new Date(o.createdAt).toLocaleString(undefined, { month: \"short\", day: \"numeric\", hour: \"numeric\", minute: \"2-digit\" }),\n  };\n}\n\nasync function loadOrdersFromServer() {\n  const { orders } = await apiFetch(\"/admin/orders\");\n  ORDERS = orders.map(mapOrderFromApi);\n}\n\nasync function setOrderStatusOnServer(mongoId, uiStatus) {\n  const { order } = await apiFetch(`/admin/orders/${mongoId}/status`, {\n    method: \"PATCH\",\n    body: { orderStatus: STATUS_TO_API[uiStatus] },\n  });\n  return order;\n}\n\nasync function loadCustomersFromServer() {\n  const { customers } = await apiFetch(\"/admin/customers\");\n  CUSTOMERS = customers.map(c => ({\n    id: c._id,\n    name: c.name,\n    email: c.email,\n    phone: \"\u2014\", // not collected at registration in this build\n    orders: c.orders,\n    spent: c.spent,\n    joined: new Date(c.createdAt).toLocaleDateString(undefined, { month: \"short\", year: \"numeric\" }),\n  }));\n}\n\nasync function loadCouponsFromServer() {\n  const { coupons } = await apiFetch(\"/admin/coupons\");\n  COUPONS = coupons.map(c => ({ code: c.code, type: c.type, value: c.value, minSubtotal: c.minSubtotal, maxDiscount: c.maxDiscount, active: c.active }));\n}\n\nfunction mapProductFromApi(p) {\n  return { id: p.legacyId, _dbId: p._id, title: p.title, emoji: p.emoji, img: p.img, cat: p.cat, price: p.price, old: p.old, rating: p.rating, flash: p.flash, eta: p.eta, stock: p.stock, active: p.active };\n}\n\nasync function loadProductsFromServer() {\n  const { products } = await apiFetch(\"/admin/products\");\n  PRODUCTS = products.map(mapProductFromApi);\n  _nextProductId = PRODUCTS.reduce((max, p) => Math.max(max, p.id), 0) + 1;\n}\n\n/* ============================================================\n   DATA\n   ============================================================ */\nconst CATEGORIES = [\"Grocery\",\"Electronics\",\"Home\",\"Fashion\",\"Beauty\"];\nconst EMOJI_CHOICES = [\"\ud83c\udfa7\",\"\ud83e\udd51\",\"\u231a\",\"\u2615\",\"\ud83d\udca1\",\"\ud83d\udc55\",\"\ud83e\uddf4\",\"\u2328\ufe0f\",\"\ud83c\udf5e\",\"\ud83d\udd0a\",\"\ud83d\udd6f\ufe0f\",\"\ud83d\udc5f\",\"\ud83d\udcf1\",\"\ud83e\uddfa\",\"\ud83c\udf6b\",\"\ud83e\uddc3\"];\nconst ORDER_STATUSES = [\"Placed\",\"Packing\",\"Out for delivery\",\"Delivered\",\"Cancelled\"];\nconst BOARD_STATUSES = [\"Placed\",\"Packing\",\"Out for delivery\",\"Delivered\"];\nconst NEXT_STATUS = {\"Placed\":\"Packing\",\"Packing\":\"Out for delivery\",\"Out for delivery\":\"Delivered\"};\nconst COL_META = {\n  \"Placed\":     {dot:\"var(--amber-500)\"},\n  \"Packing\":    {dot:\"var(--bolt-500)\"},\n  \"Out for delivery\": {dot:\"var(--bolt-900)\"},\n  \"Delivered\":  {dot:\"var(--live-500)\"},\n};\n\nlet PRODUCTS = []; // populated by loadProductsFromServer() after login\nlet _nextProductId = 1; // recomputed by loadProductsFromServer()\n\nlet ORDERS = []; // populated by loadOrdersFromServer() after login\nlet currentOrderFilter = \"All\";\nlet currentOrderSubtab = \"board\";\n\n// RIDERS stay local/demo data \u2014 there's no Rider model or assignment API in the backend\n// (the source prompt's spec didn't call for one). Rider assignment here does not persist.\nlet RIDERS = [\n  {id:1, name:\"Aman Kumar\", phone:\"+91 98111 22334\", status:\"Available\"},\n  {id:2, name:\"Divya Singh\", phone:\"+91 97222 33445\", status:\"On delivery\"},\n  {id:3, name:\"Rohit Das\", phone:\"+91 96333 44556\", status:\"Available\"},\n  {id:4, name:\"Farah Khan\", phone:\"+91 95444 55667\", status:\"Offline\"},\n  {id:5, name:\"Suresh Pillai\", phone:\"+91 94555 66778\", status:\"Available\"},\n];\n\nlet CUSTOMERS = []; // populated by loadCustomersFromServer() after login\n\n// Coupons now load from the real backend (see loadCouponsFromServer()) via\n// GET/POST/PATCH/DELETE /api/admin/coupons \u2014 the checkout pricing in\n// swiftcart-backend/routes/orders.js reads from the same Coupon collection.\nlet COUPONS = [];\nlet _editingCouponCode = null;\nlet _deletingCouponCode = null;\n\nlet SETTINGS = {\n  storeName: \"SwiftCart\",\n  supportEmail: \"help@swiftcart.example\",\n  deliveryFee: 40,\n  freeDeliveryThreshold: 200,\n  lowStockThreshold: 10,\n  maintenanceMode: false,\n};\n\nlet currentAdmin = null;\nlet authMode = \"login\"; // \"login\" only \u2014 see handleAuthSubmit(); admin accounts can't self-register\n\n/* ============================================================\n   STATE\n   ============================================================ */\nlet currentCategory = \"All\";\nlet searchQuery = \"\";\nlet sortMode = \"default\";\nlet editingId = null;      // product id being edited, or null\nlet deleteTarget = null;   // {type:\"product\"|\"coupon\", id}\nlet selectedEmoji = \"\ud83c\udfa7\";\n\n/* ============================================================\n   HELPERS\n   ============================================================ */\nfunction fmtMoney(n){ return \"\u20b9\" + Number(n).toLocaleString(\"en-IN\"); }\nfunction stockStatus(qty){\n  if(qty <= 0) return {cls:\"out\", label:\"Out of stock\"};\n  if(qty <= SETTINGS.lowStockThreshold) return {cls:\"low\", label:\"Low stock\"};\n  return {cls:\"in\", label:\"In stock\"};\n}\nfunction statusClass(status){\n  return \"st-\" + status.toLowerCase().replace(/\\s+/g,\"\");\n}\nfunction initials(name){\n  return name.split(\" \").map(w=>w[0]).slice(0,2).join(\"\").toUpperCase();\n}\nfunction toast(msg){\n  const t = document.getElementById(\"toast\");\n  t.textContent = msg;\n  t.classList.add(\"show\");\n  clearTimeout(t._timer);\n  t._timer = setTimeout(()=> t.classList.remove(\"show\"), 2200);\n}\n\n/* ============================================================\n   VIEW SWITCHING\n   ============================================================ */\nconst VIEW_META = {\n  overview:  {title:\"Overview\",  sub:\"What needs your attention right now\"},\n  products:  {title:\"Products\",  sub:\"Manage your live catalog\"},\n  orders:    {title:\"Orders\",    sub:\"Live board and full order history\"},\n  riders:    {title:\"Riders\",    sub:\"Delivery fleet and live assignments\"},\n  customers: {title:\"Customers\", sub:\"Everyone who has shopped with you\"},\n  coupons:   {title:\"Coupons\",   sub:\"Discount codes available at checkout\"},\n  settings:  {title:\"Settings\",  sub:\"Store-wide configuration\"},\n};\nfunction switchView(view){\n  document.querySelectorAll(\".view\").forEach(v=> v.classList.remove(\"active\"));\n  document.getElementById(\"view-\" + view).classList.add(\"active\");\n  document.querySelectorAll(\".side-link\").forEach(l=> l.classList.toggle(\"active\", l.dataset.view === view));\n  document.getElementById(\"pageTitle\").textContent = VIEW_META[view].title;\n  document.getElementById(\"pageSub\").textContent = VIEW_META[view].sub;\n\n  const addBtn = document.getElementById(\"addProductBtn\");\n  const search = document.querySelector(\".top-search\");\n  addBtn.style.display = (view === \"products\") ? \"flex\" : \"none\";\n  search.style.display = (view === \"products\") ? \"\" : \"none\";\n\n  if(view === \"overview\") renderOverview();\n  if(view === \"orders\") renderOrders();\n  if(view === \"riders\") renderRiders();\n  if(view === \"customers\") renderCustomers();\n  if(view === \"coupons\") renderCoupons();\n  if(view === \"settings\") fillSettingsForm();\n\n  toggleSidebar(false);\n}\n\n/* ============================================================\n   PRODUCTS \u2014 CATEGORY FILTER PILLS\n   ============================================================ */\nfunction renderCatFilters(){\n  const wrap = document.getElementById(\"catFilters\");\n  const all = [\"All\", ...CATEGORIES];\n  wrap.innerHTML = all.map(c => `<button class=\"cat-pill ${c===currentCategory?\"active\":\"\"}\" data-cat=\"${c}\">${c}</button>`).join(\"\");\n  wrap.querySelectorAll(\".cat-pill\").forEach(btn=>{\n    btn.onclick = ()=>{ currentCategory = btn.dataset.cat; renderCatFilters(); renderTable(); };\n  });\n}\n\nfunction getFilteredProducts(){\n  let list = PRODUCTS.slice();\n  if(currentCategory !== \"All\") list = list.filter(p => p.cat === currentCategory);\n  if(searchQuery.trim()){\n    const q = searchQuery.trim().toLowerCase();\n    list = list.filter(p => p.title.toLowerCase().includes(q) || p.cat.toLowerCase().includes(q));\n  }\n  switch(sortMode){\n    case \"price-asc\": list.sort((a,b)=> a.price - b.price); break;\n    case \"price-desc\": list.sort((a,b)=> b.price - a.price); break;\n    case \"stock-asc\": list.sort((a,b)=> a.stock - b.stock); break;\n    case \"rating-desc\": list.sort((a,b)=> b.rating - a.rating); break;\n    default: list.sort((a,b)=> a.id - b.id);\n  }\n  return list;\n}\n\nfunction renderTable(){\n  const body = document.getElementById(\"productsBody\");\n  const list = getFilteredProducts();\n  if(list.length === 0){\n    body.innerHTML = `<tr><td colspan=\"7\"><div class=\"empty-row\"><div class=\"e\">\ud83d\udce6</div>No products match this filter.<br>Try a different search or category.</div></td></tr>`;\n  } else {\n    body.innerHTML = list.map(p=>{\n      const st = stockStatus(p.stock);\n      return `\n      <tr data-id=\"${p.id}\">\n        <td>\n          <div class=\"prod-cell\">\n            <div class=\"prod-thumb\">${p.img ? `<img src=\"${p.img}\" alt=\"${p.title}\" loading=\"lazy\" onerror=\"this.replaceWith(Object.assign(document.createElement('span'),{textContent:'${p.emoji}'}))\" />` : p.emoji}</div>\n            <div>\n              <div class=\"prod-title\">${p.title}</div>\n              <div class=\"prod-id\">#${String(p.id).padStart(4,\"0\")} \u00b7 ${p.eta} delivery</div>\n            </div>\n          </div>\n        </td>\n        <td><span class=\"cat-tag\">${p.cat}</span></td>\n        <td class=\"price-cell\"><b>${fmtMoney(p.price)}</b>${p.old ? `<span class=\"price-old\">${fmtMoney(p.old)}</span>` : \"\"}</td>\n        <td>\n          <div style=\"display:flex;align-items:center;gap:8px\">\n            <input type=\"number\" min=\"0\" class=\"stock-input\" value=\"${p.stock}\" data-stock-id=\"${p.id}\" />\n            <span class=\"stock-pill ${st.cls}\"><span class=\"dot\"></span>${st.label}</span>\n            <button class=\"stock-toggle-btn\" data-quick-stock=\"${p.id}\">${p.stock<=0 ? \"Mark in-stock\" : \"Mark out\"}</button>\n          </div>\n        </td>\n        <td><div class=\"rating-cell\">\u2605 ${p.rating.toFixed(1)}</div></td>\n        <td><button class=\"flash-toggle ${p.flash?\"on\":\"\"}\" data-flash-id=\"${p.id}\" aria-label=\"Toggle flash sale\"></button></td>\n        <td>\n          <div class=\"row-actions\">\n            <button class=\"icon-action\" data-edit-id=\"${p.id}\" aria-label=\"Edit\">\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>\n            </button>\n            <button class=\"icon-action danger\" data-delete-id=\"${p.id}\" aria-label=\"Delete\">\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n            </button>\n          </div>\n        </td>\n      </tr>`;\n    }).join(\"\");\n  }\n  bindRowEvents();\n  renderStats();\n}\n\nfunction bindRowEvents(){\n  document.querySelectorAll(\"[data-flash-id]\").forEach(btn=>{\n    btn.onclick = ()=>{\n      const id = Number(btn.dataset.flashId);\n      const p = PRODUCTS.find(x=>x.id===id);\n      p.flash = !p.flash;\n      toast(p.flash ? `${p.title} added to flash sale` : `${p.title} removed from flash sale`);\n      renderTable();\n    };\n  });\n  document.querySelectorAll(\"[data-stock-id]\").forEach(inp=>{\n    inp.onchange = ()=>{\n      const id = Number(inp.dataset.stockId);\n      const p = PRODUCTS.find(x=>x.id===id);\n      const val = Math.max(0, Math.round(Number(inp.value) || 0));\n      p.stock = val;\n      toast(`Stock updated for ${p.title}`);\n      renderTable();\n    };\n  });\n  document.querySelectorAll(\"[data-edit-id]\").forEach(btn=>{\n    btn.onclick = ()=> openProductModal(Number(btn.dataset.editId));\n  });\n  document.querySelectorAll(\"[data-delete-id]\").forEach(btn=>{\n    btn.onclick = ()=> openDeleteModal(\"product\", Number(btn.dataset.deleteId));\n  });\n  document.querySelectorAll(\"[data-quick-stock]\").forEach(btn=>{\n    btn.onclick = ()=>{\n      const id = Number(btn.dataset.quickStock);\n      const p = PRODUCTS.find(x=>x.id===id);\n      if(p.stock > 0){\n        p._prevStock = p.stock;\n        p.stock = 0;\n        toast(`${p.title} marked out of stock`);\n      } else {\n        p.stock = p._prevStock && p._prevStock > 0 ? p._prevStock : (SETTINGS.lowStockThreshold + 10);\n        toast(`${p.title} marked back in stock`);\n      }\n      renderTable();\n    };\n  });\n}\n\nfunction renderStats(){\n  const total = PRODUCTS.length;\n  const oos = PRODUCTS.filter(p=>p.stock<=0).length;\n  const flash = PRODUCTS.filter(p=>p.flash).length;\n  const value = PRODUCTS.reduce((s,p)=> s + p.price*p.stock, 0);\n  document.getElementById(\"statTotal\").textContent = total;\n  document.getElementById(\"statOOS\").textContent = oos;\n  document.getElementById(\"statFlash\").textContent = flash;\n  document.getElementById(\"statValue\").textContent = fmtMoney(value);\n  document.getElementById(\"statOOSDelta\").textContent = oos===0 ? \"all products stocked\" : \"needs restocking\";\n  document.getElementById(\"statFlashDelta\").textContent = flash===0 ? \"no active promos\" : \"live right now\";\n\n  const low = PRODUCTS.filter(p=> p.stock > 0 && p.stock <= SETTINGS.lowStockThreshold);\n  const alertWrap = document.getElementById(\"lowStockAlert\");\n  if(low.length === 0){\n    alertWrap.innerHTML = \"\";\n  } else {\n    alertWrap.innerHTML = `\n    <div class=\"alert-banner\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\n      <span><b>${low.length} item${low.length>1?\"s\":\"\"} running low</b> (\u2264${SETTINGS.lowStockThreshold} units) \u2014 ${low.map(p=>p.title).join(\", \")}</span>\n    </div>`;\n  }\n}\n\n/* ============================================================\n   OVERVIEW\n   ============================================================ */\nfunction renderOverview(){\n  const todays = ORDERS.filter(o=> o.placed.indexOf(\"Today\") === 0);\n  const todaysRevenue = todays.filter(o=> o.status !== \"Cancelled\").reduce((s,o)=> s+o.total, 0);\n  const activeDeliveries = ORDERS.filter(o=> o.status === \"Out for delivery\").length;\n  const lowStockList = PRODUCTS.filter(p=> p.stock <= SETTINGS.lowStockThreshold).sort((a,b)=> a.stock - b.stock);\n  const needsAttention = ORDERS\n    .filter(o=> o.status === \"Placed\" || (o.status === \"Out for delivery\" && !o.riderId));\n    // already newest-first from the server\n\n  document.getElementById(\"ovRevenue\").textContent = fmtMoney(todaysRevenue);\n  document.getElementById(\"ovOrders\").textContent = todays.length;\n  document.getElementById(\"ovActiveDeliveries\").textContent = activeDeliveries;\n  document.getElementById(\"ovLowStock\").textContent = lowStockList.length;\n  document.getElementById(\"ovLowStockDelta\").textContent = lowStockList.length === 0 ? \"all products stocked\" : \"need restocking\";\n\n  const attnWrap = document.getElementById(\"ovAttentionList\");\n  attnWrap.innerHTML = needsAttention.length === 0\n    ? `<div class=\"ov-empty\"><div class=\"e\">\u2705</div>Nothing needs attention right now.</div>`\n    : needsAttention.slice(0,6).map(o=> `\n      <div class=\"ov-row\">\n        <div class=\"avatar-chip\">${initials(o.customer)}</div>\n        <div class=\"ov-row-main\">\n          <div class=\"ov-row-title\">${shortOrderId(o.id)} \u00b7 ${o.customer}</div>\n          <div class=\"ov-row-sub\">${o.status === \"Placed\" ? \"Awaiting packing\" : \"No rider assigned\"} \u00b7 ${fmtMoney(o.total)}</div>\n        </div>\n        <span class=\"status-pill ${statusClass(o.status)}\">${o.status}</span>\n      </div>`).join(\"\");\n\n  const lsWrap = document.getElementById(\"ovLowStockList\");\n  lsWrap.innerHTML = lowStockList.length === 0\n    ? `<div class=\"ov-empty\"><div class=\"e\">\ud83d\udce6</div>All products are stocked.</div>`\n    : lowStockList.slice(0,6).map(p=>{\n      const st = stockStatus(p.stock);\n      return `\n      <div class=\"ov-row\">\n        <div class=\"prod-thumb\" style=\"width:34px;height:34px;font-size:16px\">${p.img ? `<img src=\"${p.img}\" alt=\"${p.title}\" loading=\"lazy\" onerror=\"this.replaceWith(Object.assign(document.createElement('span'),{textContent:'${p.emoji}'}))\" />` : p.emoji}</div>\n        <div class=\"ov-row-main\">\n          <div class=\"ov-row-title\">${p.title}</div>\n          <div class=\"ov-row-sub\">${p.cat}</div>\n        </div>\n        <span class=\"stock-pill ${st.cls}\"><span class=\"dot\"></span>${p.stock} left</span>\n      </div>`;\n    }).join(\"\");\n\n  const recWrap = document.getElementById(\"ovRecentBody\");\n  const recent = ORDERS.slice(0,5); // already newest-first from the server\n  recWrap.innerHTML = recent.map(o=> `\n    <tr>\n      <td><b>${shortOrderId(o.id)}</b></td>\n      <td>\n        <div class=\"prod-cell\">\n          <div class=\"avatar-chip\">${initials(o.customer)}</div>\n          <div class=\"prod-title\">${o.customer}</div>\n        </div>\n      </td>\n      <td class=\"price-cell\"><b>${fmtMoney(o.total)}</b></td>\n      <td><span class=\"status-pill ${statusClass(o.status)}\">${o.status}</span></td>\n    </tr>`).join(\"\");\n}\n\n/* ============================================================\n   PRODUCTS \u2014 ADD / EDIT MODAL\n   ============================================================ */\nfunction fillCatSelect(){\n  const sel = document.getElementById(\"fCat\");\n  sel.innerHTML = CATEGORIES.map(c=>`<option value=\"${c}\">${c}</option>`).join(\"\");\n}\nfunction fillEmojiRow(){\n  const row = document.getElementById(\"emojiRow\");\n  row.innerHTML = EMOJI_CHOICES.map(e=>`<button type=\"button\" class=\"emoji-choice ${e===selectedEmoji?\"active\":\"\"}\" data-emoji=\"${e}\">${e}</button>`).join(\"\");\n  row.querySelectorAll(\".emoji-choice\").forEach(btn=>{\n    btn.onclick = ()=>{\n      selectedEmoji = btn.dataset.emoji;\n      document.getElementById(\"fEmoji\").value = selectedEmoji;\n      row.querySelectorAll(\".emoji-choice\").forEach(b=>b.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n    };\n  });\n}\nfunction openProductModal(id){\n  editingId = id || null;\n  document.getElementById(\"productFormError\").classList.remove(\"show\");\n  fillCatSelect();\n\n  if(editingId){\n    const p = PRODUCTS.find(x=>x.id===editingId);\n    document.getElementById(\"productModalTitle\").textContent = \"Edit product\";\n    document.getElementById(\"productModalSub\").textContent = `Editing #${String(p.id).padStart(4,\"0\")} \u2014 changes apply immediately.`;\n    document.getElementById(\"fTitle\").value = p.title;\n    document.getElementById(\"fEmoji\").value = p.emoji;\n    selectedEmoji = p.emoji;\n    document.getElementById(\"fCat\").value = p.cat;\n    document.getElementById(\"fEta\").value = p.eta;\n    document.getElementById(\"fPrice\").value = p.price;\n    document.getElementById(\"fOld\").value = p.old || \"\";\n    document.getElementById(\"fRating\").value = p.rating;\n    document.getElementById(\"fStock\").value = p.stock;\n    document.getElementById(\"fFlashToggle\").classList.toggle(\"on\", !!p.flash);\n    document.getElementById(\"productSubmit\").textContent = \"Save changes\";\n  } else {\n    document.getElementById(\"productModalTitle\").textContent = \"Add product\";\n    document.getElementById(\"productModalSub\").textContent = \"Fill in the details below to add it to the catalog.\";\n    document.getElementById(\"fTitle\").value = \"\";\n    document.getElementById(\"fEmoji\").value = \"\ud83c\udfa7\";\n    selectedEmoji = \"\ud83c\udfa7\";\n    document.getElementById(\"fCat\").value = CATEGORIES[0];\n    document.getElementById(\"fEta\").value = \"\";\n    document.getElementById(\"fPrice\").value = \"\";\n    document.getElementById(\"fOld\").value = \"\";\n    document.getElementById(\"fRating\").value = \"\";\n    document.getElementById(\"fStock\").value = \"\";\n    document.getElementById(\"fFlashToggle\").classList.remove(\"on\");\n    document.getElementById(\"productSubmit\").textContent = \"Save product\";\n  }\n  fillEmojiRow();\n  document.getElementById(\"productOverlay\").classList.add(\"show\");\n}\nfunction closeProductModal(){\n  document.getElementById(\"productOverlay\").classList.remove(\"show\");\n  editingId = null;\n}\nasync function handleProductSubmit(e){\n  if(e && e.preventDefault) e.preventDefault();\n  const errEl = document.getElementById(\"productFormError\");\n  errEl.classList.remove(\"show\");\n\n  const title = document.getElementById(\"fTitle\").value.trim();\n  const emoji = document.getElementById(\"fEmoji\").value.trim() || \"\ud83d\udce6\";\n  const cat = document.getElementById(\"fCat\").value;\n  const eta = document.getElementById(\"fEta\").value.trim() || \"15 min\";\n  const price = Math.round(Number(document.getElementById(\"fPrice\").value));\n  const oldRaw = document.getElementById(\"fOld\").value;\n  const old = oldRaw ? Math.round(Number(oldRaw)) : null;\n  const rating = Number(document.getElementById(\"fRating\").value) || 4.5;\n  const stock = Math.max(0, Math.round(Number(document.getElementById(\"fStock\").value) || 0));\n  const flash = document.getElementById(\"fFlashToggle\").classList.contains(\"on\");\n\n  if(!title){ errEl.textContent = \"Please give the product a title.\"; errEl.classList.add(\"show\"); return; }\n  if(!price || price <= 0){ errEl.textContent = \"Please enter a valid price.\"; errEl.classList.add(\"show\"); return; }\n  if(old !== null && old <= price){ errEl.textContent = \"Old price should be higher than the current price.\"; errEl.classList.add(\"show\"); return; }\n\n  const submitBtn = document.getElementById(\"productSubmit\");\n  submitBtn.disabled = true;\n  try {\n    if(editingId){\n      const p = PRODUCTS.find(x=>x.id===editingId);\n      const { product } = await apiFetch(`/admin/products/${p._dbId}`, {\n        method: \"PATCH\",\n        body: { title, emoji, cat, eta, price, old, rating, stock, flash },\n      });\n      Object.assign(p, mapProductFromApi(product));\n      toast(`${title} updated`);\n    } else {\n      const legacyId = _nextProductId++;\n      const { product } = await apiFetch(\"/admin/products\", {\n        method: \"POST\",\n        body: { legacyId, title, emoji, cat, eta, price, old, rating, stock, flash },\n      });\n      PRODUCTS.push(mapProductFromApi(product));\n      toast(`${title} added to catalog`);\n    }\n    closeProductModal();\n    renderCatFilters();\n    renderTable();\n  } catch (err) {\n    errEl.textContent = err.message || \"Couldn't save this product. Please try again.\";\n    errEl.classList.add(\"show\");\n  } finally {\n    submitBtn.disabled = false;\n  }\n}\n\n/* ============================================================\n   ORDERS\n   ============================================================ */\nfunction riderName(id){\n  const r = RIDERS.find(x=>x.id===id);\n  return r ? r.name : null;\n}\nfunction computeAvgEta(){\n  const done = ORDERS.filter(o=>o.status===\"Delivered\" && o.etaMin);\n  if(done.length===0) return \"12 min\";\n  const avg = Math.round(done.reduce((s,o)=>s+o.etaMin,0)/done.length);\n  return avg + \" min\";\n}\nfunction renderOrderStats(){\n  const live = ORDERS.filter(o=> o.status!==\"Delivered\" && o.status!==\"Cancelled\").length;\n  const outForDelivery = ORDERS.filter(o=> o.status===\"Out for delivery\").length;\n  const codDue = ORDERS.filter(o=> o.payment===\"COD\" && !o.paid && o.status!==\"Cancelled\").reduce((s,o)=>s+o.total,0);\n  document.getElementById(\"statLiveOrders\").textContent = live;\n  document.getElementById(\"statOutForDelivery\").textContent = outForDelivery;\n  document.getElementById(\"statAvgEta\").textContent = computeAvgEta();\n  document.getElementById(\"statCodDue\").textContent = fmtMoney(codDue);\n}\nfunction payBadge(o){\n  return o.paid\n    ? `<span class=\"pay-badge paid\">\u2713 Paid \u00b7 ${o.payment}</span>`\n    : `<span class=\"pay-badge due\">\u20b9 Due \u00b7 COD</span>`;\n}\nfunction shortOrderId(id){ return \"#\" + String(id).slice(-8).toUpperCase(); }\n\nfunction renderKanban(){\n  const board = document.getElementById(\"kanbanBoard\");\n  board.innerHTML = BOARD_STATUSES.map(status=>{\n    const items = ORDERS.filter(o=>o.status===status); // already newest-first from the server\n    const meta = COL_META[status];\n    const cards = items.length ? items.map(o=>{\n      const canAdvance = !!NEXT_STATUS[status];\n      return `\n      <div class=\"kcard\" data-order-id=\"${o.id}\">\n        <div class=\"kcard-top\">\n          <span class=\"kcard-id\">${shortOrderId(o.id)}</span>\n          ${payBadge(o)}\n        </div>\n        <div class=\"kcard-cust\">\n          <div class=\"avatar-chip\" style=\"width:26px;height:26px;font-size:11px\">${initials(o.customer)}</div>\n          <div class=\"name\">${o.customer}</div>\n        </div>\n        <div class=\"kcard-meta\">\n          <span>${o.items} item${o.items>1?\"s\":\"\"} \u00b7 ${fmtMoney(o.total)}</span>\n          <span>${o.placed}</span>\n        </div>\n        <div class=\"kcard-rider\">\n          <select data-assign-rider=\"${o.id}\">\n            <option value=\"\">Unassigned</option>\n            ${RIDERS.map(r=>`<option value=\"${r.id}\" ${o.riderId===r.id?\"selected\":\"\"}>${r.name} ${r.status===\"Available\"?\"\u00b7 Available\":r.status===\"On delivery\"?\"\u00b7 Busy\":\"\u00b7 Offline\"}</option>`).join(\"\")}\n          </select>\n        </div>\n        <div class=\"kcard-actions\">\n          ${canAdvance ? `<button class=\"kcard-advance\" data-advance=\"${o.id}\">Mark as ${NEXT_STATUS[status]}</button>` : `<button class=\"kcard-advance\" style=\"background:var(--live-500)\" disabled>Delivered</button>`}\n          <button class=\"kcard-cancel\" data-cancel=\"${o.id}\" aria-label=\"Cancel order\" title=\"Cancel order\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M18 6 6 18\"/><path d=\"m6 6 12 12\"/></svg>\n          </button>\n        </div>\n      </div>`;\n    }).join(\"\") : `<div class=\"kcol-empty\">No orders here</div>`;\n\n    return `\n    <div class=\"kcol\">\n      <div class=\"kcol-head\">\n        <span class=\"kcol-dot\" style=\"background:${meta.dot}\"></span>\n        <span class=\"kcol-title\">${status}</span>\n        <span class=\"kcol-count\">${items.length}</span>\n      </div>\n      <div class=\"kcol-body\">${cards}</div>\n    </div>`;\n  }).join(\"\");\n\n  board.querySelectorAll(\"[data-advance]\").forEach(btn=>{\n    btn.onclick = async ()=>{\n      const id = btn.dataset.advance;\n      const o = ORDERS.find(x=>x.id===id);\n      const next = NEXT_STATUS[o.status];\n      if(!next) return;\n      if(next === \"Out for delivery\" && !o.riderId){\n        toast(\"Assign a rider before sending it out for delivery\");\n        return;\n      }\n      btn.disabled = true;\n      try {\n        await setOrderStatusOnServer(id, next);\n        o.status = next;\n        if(next === \"Delivered\" && !o.etaMin) o.etaMin = 9 + Math.floor(Math.random()*14);\n        toast(`Order ${shortOrderId(o.id)} marked as ${next}`);\n      } catch (err) {\n        toast(err.message || \"Couldn't update the order.\");\n      }\n      renderOrders();\n      renderRiders();\n    };\n  });\n  board.querySelectorAll(\"[data-cancel]\").forEach(btn=>{\n    btn.onclick = async ()=>{\n      const id = btn.dataset.cancel;\n      const o = ORDERS.find(x=>x.id===id);\n      btn.disabled = true;\n      try {\n        await setOrderStatusOnServer(id, \"Cancelled\");\n        o.status = \"Cancelled\";\n        toast(`Order ${shortOrderId(o.id)} cancelled`);\n      } catch (err) {\n        toast(err.message || \"Couldn't cancel the order.\");\n      }\n      renderOrders();\n      renderRiders();\n    };\n  });\n  board.querySelectorAll(\"[data-assign-rider]\").forEach(sel=>{\n    sel.onchange = ()=>{\n      // Local only \u2014 no rider-assignment endpoint on the backend (see RIDERS comment above).\n      const id = sel.dataset.assignRider;\n      const o = ORDERS.find(x=>x.id===id);\n      o.riderId = sel.value ? Number(sel.value) : null;\n      const r = RIDERS.find(x=>x.id===o.riderId);\n      toast(r ? `${r.name} assigned to order ${shortOrderId(o.id)} (local only)` : `Rider unassigned from order ${shortOrderId(o.id)}`);\n      renderRiders();\n    };\n  });\n}\nfunction renderOrderFilters(){\n  const wrap = document.getElementById(\"orderFilters\");\n  const all = [\"All\", ...ORDER_STATUSES];\n  wrap.innerHTML = all.map(s => `<button class=\"cat-pill ${s===currentOrderFilter?\"active\":\"\"}\" data-status=\"${s}\">${s}</button>`).join(\"\");\n  wrap.querySelectorAll(\".cat-pill\").forEach(btn=>{\n    btn.onclick = ()=>{ currentOrderFilter = btn.dataset.status; renderOrderFilters(); renderOrdersTable(); };\n  });\n}\nfunction renderOrdersTable(){\n  const body = document.getElementById(\"ordersBody\");\n  let list = ORDERS.slice(); // already newest-first from the server\n  if(currentOrderFilter !== \"All\") list = list.filter(o => o.status === currentOrderFilter);\n\n  if(list.length === 0){\n    body.innerHTML = `<tr><td colspan=\"8\"><div class=\"empty-row\"><div class=\"e\">\ud83e\uddfe</div>No orders with this status.</div></td></tr>`;\n    return;\n  }\n  body.innerHTML = list.map(o => `\n    <tr data-order-id=\"${o.id}\">\n      <td><b>${shortOrderId(o.id)}</b></td>\n      <td>\n        <div class=\"prod-cell\">\n          <div class=\"avatar-chip\">${initials(o.customer)}</div>\n          <div class=\"prod-title\">${o.customer}</div>\n        </div>\n      </td>\n      <td>${o.items} item${o.items>1?\"s\":\"\"}</td>\n      <td class=\"price-cell\"><b>${fmtMoney(o.total)}</b></td>\n      <td>${payBadge(o)}</td>\n      <td style=\"color:var(--ink-soft)\">${riderName(o.riderId) || \"\u2014\"}</td>\n      <td style=\"color:var(--ink-soft)\">${o.placed}</td>\n      <td>\n        <select class=\"status-select\" data-order-status=\"${o.id}\">\n          ${ORDER_STATUSES.map(s => `<option value=\"${s}\" ${s===o.status?\"selected\":\"\"}>${s}</option>`).join(\"\")}\n        </select>\n      </td>\n    </tr>\n  `).join(\"\");\n\n  document.querySelectorAll(\"[data-order-status]\").forEach(sel=>{\n    sel.onchange = async ()=>{\n      const id = sel.dataset.orderStatus;\n      const o = ORDERS.find(x=>x.id===id);\n      const newStatus = sel.value;\n      sel.disabled = true;\n      try {\n        await setOrderStatusOnServer(id, newStatus);\n        o.status = newStatus;\n        toast(`Order ${shortOrderId(o.id)} marked as ${newStatus}`);\n      } catch (err) {\n        sel.value = o.status; // revert the dropdown on failure\n        toast(err.message || \"Couldn't update the order.\");\n      }\n      sel.disabled = false;\n      renderOrdersTable();\n      renderOrderStats();\n      renderRiders();\n    };\n  });\n}\nfunction switchOrderSubtab(tab){\n  currentOrderSubtab = tab;\n  document.querySelectorAll(\"#orderSubtabs .subtab\").forEach(b=> b.classList.toggle(\"active\", b.dataset.subtab===tab));\n  document.getElementById(\"orderBoardWrap\").style.display = tab===\"board\" ? \"\" : \"none\";\n  document.getElementById(\"orderTableWrap\").style.display = tab===\"table\" ? \"\" : \"none\";\n  document.getElementById(\"orderFilters\").style.display = tab===\"table\" ? \"flex\" : \"none\";\n}\nfunction renderOrders(){\n  renderOrderStats();\n  renderKanban();\n  renderOrderFilters();\n  renderOrdersTable();\n}\n\n/* ============================================================\n   RIDERS\n   ============================================================ */\nfunction renderRiders(){\n  const avail = RIDERS.filter(r=>r.status===\"Available\").length;\n  const onDel = RIDERS.filter(r=>r.status===\"On delivery\").length;\n  document.getElementById(\"statRidersAvail\").textContent = avail;\n  document.getElementById(\"statRidersOnDelivery\").textContent = onDel;\n  document.getElementById(\"statRidersTotal\").textContent = RIDERS.length;\n  document.getElementById(\"statAvgEta2\").textContent = computeAvgEta();\n\n  const grid = document.getElementById(\"riderGrid\");\n  grid.innerHTML = RIDERS.map(r=>{\n    const load = ORDERS.filter(o=> o.riderId===r.id && o.status!==\"Delivered\" && o.status!==\"Cancelled\").length;\n    return `\n    <div class=\"rider-card\">\n      <div class=\"rider-top\">\n        <div class=\"avatar-chip\" style=\"width:38px;height:38px;font-size:14px\">${initials(r.name)}</div>\n        <div>\n          <div class=\"rider-name\">${r.name}</div>\n          <div class=\"rider-phone\">${r.phone}</div>\n        </div>\n      </div>\n      <select class=\"rstatus-select\" data-rider-status=\"${r.id}\">\n        <option value=\"Available\" ${r.status===\"Available\"?\"selected\":\"\"}>Available</option>\n        <option value=\"On delivery\" ${r.status===\"On delivery\"?\"selected\":\"\"}>On delivery</option>\n        <option value=\"Offline\" ${r.status===\"Offline\"?\"selected\":\"\"}>Offline</option>\n      </select>\n      <div class=\"rider-stats\">\n        <div class=\"rider-load\">Active orders: <b>${load}</b></div>\n      </div>\n    </div>`;\n  }).join(\"\");\n\n  grid.querySelectorAll(\"[data-rider-status]\").forEach(sel=>{\n    sel.onchange = ()=>{\n      const id = Number(sel.dataset.riderStatus);\n      const r = RIDERS.find(x=>x.id===id);\n      r.status = sel.value;\n      toast(`${r.name} marked as ${r.status}`);\n      renderRiders();\n      renderKanban();\n    };\n  });\n}\n\n/* ============================================================\n   CUSTOMERS\n   ============================================================ */\nfunction renderCustomers(){\n  const body = document.getElementById(\"customersBody\");\n  const list = CUSTOMERS.slice().sort((a,b)=> b.spent - a.spent);\n  body.innerHTML = list.map(c => `\n    <tr>\n      <td>\n        <div class=\"prod-cell\">\n          <div class=\"avatar-chip\">${initials(c.name)}</div>\n          <div class=\"prod-title\">${c.name}</div>\n        </div>\n      </td>\n      <td>\n        <div style=\"font-size:13px\">${c.email}</div>\n        <div style=\"font-size:11.5px;color:var(--ink-soft)\">${c.phone}</div>\n      </td>\n      <td>${c.orders}</td>\n      <td class=\"price-cell\"><b>${fmtMoney(c.spent)}</b></td>\n      <td style=\"color:var(--ink-soft)\">${c.joined}</td>\n    </tr>\n  `).join(\"\");\n}\n\n/* ============================================================\n   COUPONS\n   ============================================================ */\nfunction renderCoupons(){\n  const body = document.getElementById(\"couponsBody\");\n  if(COUPONS.length === 0){\n    body.innerHTML = `<tr><td colspan=\"5\"><div class=\"empty-row\"><div class=\"e\">\ud83c\udff7\ufe0f</div>No coupons yet. Add one to offer a discount at checkout.</div></td></tr>`;\n    return;\n  }\n  body.innerHTML = COUPONS.map(c => {\n    const discountLabel = c.type === \"percent\"\n      ? `${c.value}% off${c.maxDiscount ? ` (max ${fmtMoney(c.maxDiscount)})` : \"\"}`\n      : `${fmtMoney(c.value)} off`;\n    return `\n    <tr data-coupon=\"${c.code}\">\n      <td><span class=\"coupon-code-cell\">${c.code}</span></td>\n      <td>${discountLabel}</td>\n      <td>${c.minSubtotal > 0 ? fmtMoney(c.minSubtotal) : \"None\"}</td>\n      <td><button class=\"active-toggle ${c.active?\"on\":\"\"}\" data-coupon-active=\"${c.code}\" aria-label=\"Toggle enabled\"></button></td>\n      <td>\n        <div class=\"row-actions\">\n          <button class=\"icon-action\" data-coupon-edit=\"${c.code}\" aria-label=\"Edit\">\n            <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>\n          </button>\n          <button class=\"icon-action danger\" data-coupon-delete=\"${c.code}\" aria-label=\"Delete\">\n            <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/><path d=\"M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6\"/></svg>\n          </button>\n        </div>\n      </td>\n    </tr>`;\n  }).join(\"\");\n\n  document.querySelectorAll(\"[data-coupon-active]\").forEach(btn=>{\n    btn.onclick = async ()=>{\n      const c = COUPONS.find(x=>x.code===btn.dataset.couponActive);\n      btn.disabled = true;\n      try {\n        const { coupon } = await apiFetch(`/admin/coupons/${c.code}`, { method: \"PATCH\", body: { active: !c.active } });\n        c.active = coupon.active;\n        toast(`${c.code} ${c.active ? \"enabled\" : \"disabled\"}`);\n      } catch (err) {\n        toast(err.message || \"Couldn't update coupon.\");\n      }\n      btn.disabled = false;\n      renderCoupons();\n    };\n  });\n  document.querySelectorAll(\"[data-coupon-edit]\").forEach(btn=>{\n    btn.onclick = ()=> openCouponModal(btn.dataset.couponEdit);\n  });\n  document.querySelectorAll(\"[data-coupon-delete]\").forEach(btn=>{\n    btn.onclick = ()=> openDeleteModal(\"coupon\", btn.dataset.couponDelete);\n  });\n}\n\nfunction updateCouponValueLabel(){\n  const type = document.getElementById(\"cType\").value;\n  document.getElementById(\"cValueLabel\").textContent = type === \"percent\" ? \"Value (%)\" : \"Value (\u20b9)\";\n}\nfunction openCouponModal(code){\n  _editingCouponCode = code || null;\n  document.getElementById(\"couponFormError\").classList.remove(\"show\");\n\n  if(_editingCouponCode){\n    const c = COUPONS.find(x=>x.code===_editingCouponCode);\n    document.getElementById(\"couponModalTitle\").textContent = \"Edit coupon\";\n    document.getElementById(\"cCode\").value = c.code;\n    document.getElementById(\"cCode\").disabled = true;\n    document.getElementById(\"cType\").value = c.type;\n    document.getElementById(\"cValue\").value = c.value;\n    document.getElementById(\"cMin\").value = c.minSubtotal || \"\";\n    document.getElementById(\"cMax\").value = c.maxDiscount || \"\";\n    document.getElementById(\"cActiveToggle\").classList.toggle(\"on\", c.active);\n    document.getElementById(\"couponSubmit\").textContent = \"Save changes\";\n  } else {\n    document.getElementById(\"couponModalTitle\").textContent = \"Add coupon\";\n    document.getElementById(\"cCode\").value = \"\";\n    document.getElementById(\"cCode\").disabled = false;\n    document.getElementById(\"cType\").value = \"percent\";\n    document.getElementById(\"cValue\").value = \"\";\n    document.getElementById(\"cMin\").value = \"\";\n    document.getElementById(\"cMax\").value = \"\";\n    document.getElementById(\"cActiveToggle\").classList.add(\"on\");\n    document.getElementById(\"couponSubmit\").textContent = \"Save coupon\";\n  }\n  updateCouponValueLabel();\n  document.getElementById(\"couponOverlay\").classList.add(\"show\");\n}\nfunction closeCouponModal(){\n  document.getElementById(\"couponOverlay\").classList.remove(\"show\");\n  document.getElementById(\"cCode\").disabled = false;\n  _editingCouponCode = null;\n}\nasync function handleCouponSubmit(e){\n  if(e && e.preventDefault) e.preventDefault();\n  const errEl = document.getElementById(\"couponFormError\");\n  errEl.classList.remove(\"show\");\n\n  const code = document.getElementById(\"cCode\").value.trim().toUpperCase();\n  const type = document.getElementById(\"cType\").value;\n  const value = Number(document.getElementById(\"cValue\").value);\n  const minSubtotal = Math.max(0, Math.round(Number(document.getElementById(\"cMin\").value) || 0));\n  const maxRaw = document.getElementById(\"cMax\").value;\n  const maxDiscount = maxRaw ? Math.round(Number(maxRaw)) : null;\n  const active = document.getElementById(\"cActiveToggle\").classList.contains(\"on\");\n\n  if(!code){ errEl.textContent = \"Please enter a coupon code.\"; errEl.classList.add(\"show\"); return; }\n  if(!_editingCouponCode && COUPONS.some(c=>c.code===code)){ errEl.textContent = \"A coupon with this code already exists.\"; errEl.classList.add(\"show\"); return; }\n  if(!value || value <= 0){ errEl.textContent = \"Please enter a valid discount value.\"; errEl.classList.add(\"show\"); return; }\n  if(type === \"percent\" && value > 100){ errEl.textContent = \"Percent discount can't exceed 100.\"; errEl.classList.add(\"show\"); return; }\n\n  const submitBtn = document.getElementById(\"couponSubmit\");\n  submitBtn.disabled = true;\n  try {\n    if(_editingCouponCode){\n      const { coupon } = await apiFetch(`/admin/coupons/${_editingCouponCode}`, {\n        method: \"PATCH\",\n        body: { type, value, minSubtotal, maxDiscount, active },\n      });\n      const c = COUPONS.find(x=>x.code===_editingCouponCode);\n      Object.assign(c, coupon);\n      toast(`${c.code} updated`);\n    } else {\n      const { coupon } = await apiFetch(\"/admin/coupons\", {\n        method: \"POST\",\n        body: { code, type, value, minSubtotal, maxDiscount, active },\n      });\n      COUPONS.push(coupon);\n      toast(`${code} added`);\n    }\n    closeCouponModal();\n    renderCoupons();\n  } catch (err) {\n    errEl.textContent = err.message || \"Couldn't save this coupon. Please try again.\";\n    errEl.classList.add(\"show\");\n  } finally {\n    submitBtn.disabled = false;\n  }\n}\n\n/* ============================================================\n   SETTINGS\n   ============================================================ */\nfunction fillSettingsForm(){\n  document.getElementById(\"setStoreName\").value = SETTINGS.storeName;\n  document.getElementById(\"setEmail\").value = SETTINGS.supportEmail;\n  document.getElementById(\"setDeliveryFee\").value = SETTINGS.deliveryFee;\n  document.getElementById(\"setFreeThreshold\").value = SETTINGS.freeDeliveryThreshold;\n  document.getElementById(\"setLowStock\").value = SETTINGS.lowStockThreshold;\n  document.getElementById(\"setMaintenanceToggle\").classList.toggle(\"on\", SETTINGS.maintenanceMode);\n}\nfunction handleSaveSettings(){\n  SETTINGS.storeName = document.getElementById(\"setStoreName\").value.trim() || SETTINGS.storeName;\n  SETTINGS.supportEmail = document.getElementById(\"setEmail\").value.trim() || SETTINGS.supportEmail;\n  SETTINGS.deliveryFee = Math.max(0, Math.round(Number(document.getElementById(\"setDeliveryFee\").value) || 0));\n  SETTINGS.freeDeliveryThreshold = Math.max(0, Math.round(Number(document.getElementById(\"setFreeThreshold\").value) || 0));\n  SETTINGS.lowStockThreshold = Math.max(0, Math.round(Number(document.getElementById(\"setLowStock\").value) || 0));\n  SETTINGS.maintenanceMode = document.getElementById(\"setMaintenanceToggle\").classList.contains(\"on\");\n  toast(\"Settings saved\");\n  renderTable(); // low-stock threshold change affects product stock pills\n}\n\n/* ============================================================\n   DELETE MODAL (shared by products + coupons)\n   ============================================================ */\nfunction openDeleteModal(type, id){\n  deleteTarget = {type, id};\n  let title, body;\n  if(type === \"product\"){\n    const p = PRODUCTS.find(x=>x.id===id);\n    title = `Remove \"${p.title}\"?`;\n    body = \"This takes it off the storefront immediately. This can't be undone.\";\n  } else {\n    title = `Remove coupon ${id}?`;\n    body = \"Shoppers will no longer be able to apply this code at checkout.\";\n  }\n  document.getElementById(\"deleteTitle\").textContent = title;\n  document.getElementById(\"deleteBody\").textContent = body;\n  document.getElementById(\"deleteOverlay\").classList.add(\"show\");\n}\nfunction closeDeleteModal(){\n  document.getElementById(\"deleteOverlay\").classList.remove(\"show\");\n  deleteTarget = null;\n}\nasync function confirmDelete(){\n  if(!deleteTarget) return;\n  const confirmBtn = document.getElementById(\"deleteConfirm\");\n  confirmBtn.disabled = true;\n  try {\n    if(deleteTarget.type === \"product\"){\n      const p = PRODUCTS.find(x=>x.id===deleteTarget.id);\n      await apiFetch(`/admin/products/${p._dbId}`, { method: \"DELETE\" });\n      PRODUCTS = PRODUCTS.filter(x=>x.id!==deleteTarget.id);\n      toast(`${p.title} removed from catalog`);\n      renderTable();\n    } else {\n      await apiFetch(`/admin/coupons/${deleteTarget.id}`, { method: \"DELETE\" });\n      COUPONS = COUPONS.filter(x=>x.code!==deleteTarget.id);\n      toast(`Coupon ${deleteTarget.id} removed`);\n      renderCoupons();\n    }\n    closeDeleteModal();\n  } catch (err) {\n    toast(err.message || \"Couldn't remove this item.\");\n  } finally {\n    confirmBtn.disabled = false;\n  }\n}\n\n/* ============================================================\n   AUTH \u2014 real backend session, admin role required.\n   Self-registration is intentionally NOT wired here: creating an admin account\n   must never be reachable from a public form. Use the seed script\n   (swiftcart-backend/utils/seedProducts.js, via SEED_ADMIN_EMAIL/PASSWORD)\n   or create additional admins directly in the database.\n   ============================================================ */\nfunction setAuthMode(mode){\n  authMode = \"login\"; // signup tab is disabled \u2014 see comment above\n  document.getElementById(\"tabLogin\").classList.add(\"active\");\n  document.getElementById(\"tabSignup\").classList.remove(\"active\");\n  document.getElementById(\"nameFieldWrap\").style.display = \"none\";\n  document.getElementById(\"confirmFieldWrap\").style.display = \"none\";\n  document.getElementById(\"authSub\").textContent = \"Sign in to manage your store\";\n  document.getElementById(\"authSubmit\").textContent = \"Sign in\";\n  document.getElementById(\"authError\").classList.remove(\"show\");\n}\nasync function handleAuthSubmit(e){\n  if(e && e.preventDefault) e.preventDefault();\n  const errEl = document.getElementById(\"authError\");\n  errEl.classList.remove(\"show\");\n\n  const email = document.getElementById(\"authEmail\").value.trim().toLowerCase();\n  const password = document.getElementById(\"authPassword\").value;\n  if(!email || !password){ errEl.textContent = \"Please fill in email and password.\"; errEl.classList.add(\"show\"); return; }\n\n  const submitBtn = document.getElementById(\"authSubmit\");\n  submitBtn.disabled = true;\n  try {\n    const { user } = await apiFetch(\"/auth/login\", { method: \"POST\", body: { email, password } });\n    if (user.role !== \"admin\") {\n      // Authentication succeeded but authorization didn't \u2014 a real customer account.\n      // Log the session back out immediately rather than leaving a non-admin signed in here.\n      await apiFetch(\"/auth/logout\", { method: \"POST\" }).catch(()=>{});\n      errEl.textContent = \"This account doesn't have store-admin access.\";\n      errEl.classList.add(\"show\");\n      return;\n    }\n    await logInAs(user);\n    toast(`Welcome back, ${user.name}!`);\n  } catch (err) {\n    errEl.textContent = err.status === 429\n      ? \"Too many attempts. Please wait a bit and try again.\"\n      : (err.message || \"Incorrect email or password.\");\n    errEl.classList.add(\"show\");\n  } finally {\n    submitBtn.disabled = false;\n  }\n}\nasync function logInAs(user){\n  currentAdmin = user;\n  document.getElementById(\"sideName\").textContent = user.name;\n  document.getElementById(\"sideRole\").textContent = \"Store manager\";\n  document.getElementById(\"sideAvatar\").textContent = initials(user.name).slice(0,2) || \"A\";\n  document.getElementById(\"authScreen\").style.display = \"none\";\n  document.getElementById(\"appRoot\").style.display = \"\";\n  document.getElementById(\"authForm\").reset();\n\n  // Pull real data before rendering the first screen.\n  try {\n    await Promise.all([loadProductsFromServer(), loadOrdersFromServer(), loadCustomersFromServer(), loadCouponsFromServer()]);\n  } catch (err) {\n    toast(\"Some data couldn't be loaded from the server.\");\n  }\n  renderCatFilters();\n  renderTable();\n  switchView(\"overview\");\n}\nasync function signOut(){\n  try { await apiFetch(\"/auth/logout\", { method: \"POST\" }); } catch (e) {}\n  currentAdmin = null;\n  document.getElementById(\"appRoot\").style.display = \"none\";\n  document.getElementById(\"authScreen\").style.display = \"flex\";\n  setAuthMode(\"login\");\n  toggleSidebar(false);\n}\n\n/** Restores an existing admin session on page load/refresh via the session cookie. */\nasync function restoreAdminSession(){\n  try {\n    const { user } = await apiFetch(\"/auth/me\");\n    if (user.role === \"admin\") { await logInAs(user); return; }\n    await apiFetch(\"/auth/logout\", { method: \"POST\" }).catch(()=>{});\n  } catch (e) { /* no valid session \u2014 show the login screen */ }\n  document.getElementById(\"authScreen\").style.display = \"flex\";\n  document.getElementById(\"appRoot\").style.display = \"none\";\n}\n\ndocument.getElementById(\"tabLogin\").onclick = ()=> setAuthMode(\"login\");\ndocument.getElementById(\"tabSignup\").onclick = ()=> toast(\"Ask an existing store admin to create your account \u2014 self-signup is disabled for admin access.\");\ndocument.getElementById(\"authForm\").onsubmit = handleAuthSubmit;\ndocument.getElementById(\"authSubmit\").onclick = handleAuthSubmit;\n[\"authName\",\"authEmail\",\"authPassword\",\"authConfirm\"].forEach(id=>{\n  const el = document.getElementById(id);\n  if(el) el.addEventListener(\"keydown\", (e)=>{ if(e.key === \"Enter\") handleAuthSubmit(e); });\n});\ndocument.getElementById(\"signOutBtn\").onclick = signOut;\n\n\n/* ============================================================\n   SIDEBAR (mobile) + NAV\n   ============================================================ */\nfunction toggleSidebar(force){\n  const sb = document.getElementById(\"sidebar\");\n  const scrim = document.getElementById(\"sidebarScrim\");\n  const open = force !== undefined ? force : !sb.classList.contains(\"open\");\n  sb.classList.toggle(\"open\", open);\n  scrim.classList.toggle(\"show\", open);\n}\ndocument.getElementById(\"menuToggle\").onclick = ()=> toggleSidebar();\ndocument.getElementById(\"sidebarScrim\").onclick = ()=> toggleSidebar(false);\ndocument.querySelectorAll(\".side-nav .side-link\").forEach(link=>{\n  link.onclick = ()=> { switchView(link.dataset.view); toggleSidebar(false); };\n});\ndocument.querySelectorAll(\"[data-goto]\").forEach(btn=>{\n  btn.onclick = ()=> switchView(btn.dataset.goto);\n});\n\n/* ============================================================\n   EVENTS\n   ============================================================ */\ndocument.getElementById(\"addProductBtn\").onclick = ()=> openProductModal(null);\ndocument.getElementById(\"productClose\").onclick = closeProductModal;\ndocument.getElementById(\"productCancel\").onclick = closeProductModal;\ndocument.getElementById(\"productOverlay\").onclick = (e)=>{ if(e.target.id===\"productOverlay\") closeProductModal(); };\ndocument.getElementById(\"productForm\").onsubmit = handleProductSubmit;\ndocument.getElementById(\"productSubmit\").onclick = handleProductSubmit;\ndocument.getElementById(\"fFlashToggle\").onclick = ()=> document.getElementById(\"fFlashToggle\").classList.toggle(\"on\");\ndocument.getElementById(\"fEmoji\").addEventListener(\"input\", (e)=>{ selectedEmoji = e.target.value; fillEmojiRow(); });\n\ndocument.getElementById(\"addCouponBtn\").onclick = ()=> openCouponModal(null);\ndocument.getElementById(\"couponClose\").onclick = closeCouponModal;\ndocument.getElementById(\"couponCancel\").onclick = closeCouponModal;\ndocument.getElementById(\"couponOverlay\").onclick = (e)=>{ if(e.target.id===\"couponOverlay\") closeCouponModal(); };\ndocument.getElementById(\"couponForm\").onsubmit = handleCouponSubmit;\ndocument.getElementById(\"couponSubmit\").onclick = handleCouponSubmit;\ndocument.getElementById(\"cType\").addEventListener(\"change\", updateCouponValueLabel);\ndocument.getElementById(\"cActiveToggle\").onclick = ()=> document.getElementById(\"cActiveToggle\").classList.toggle(\"on\");\n\ndocument.getElementById(\"deleteCancel\").onclick = closeDeleteModal;\ndocument.getElementById(\"deleteOverlay\").onclick = (e)=>{ if(e.target.id===\"deleteOverlay\") closeDeleteModal(); };\ndocument.getElementById(\"deleteConfirm\").onclick = confirmDelete;\n\ndocument.getElementById(\"saveSettingsBtn\").onclick = handleSaveSettings;\ndocument.getElementById(\"setMaintenanceToggle\").onclick = ()=> document.getElementById(\"setMaintenanceToggle\").classList.toggle(\"on\");\n\ndocument.getElementById(\"searchInput\").addEventListener(\"input\", (e)=>{ searchQuery = e.target.value; renderTable(); });\ndocument.querySelectorAll(\"#orderSubtabs .subtab\").forEach(btn=>{\n  btn.onclick = ()=> switchOrderSubtab(btn.dataset.subtab);\n});\ndocument.getElementById(\"sortSelect\").addEventListener(\"change\", (e)=>{ sortMode = e.target.value; renderTable(); });\n\ndocument.addEventListener(\"keydown\", (e)=>{\n  if(e.key === \"Escape\"){ closeProductModal(); closeCouponModal(); closeDeleteModal(); }\n});\n\n/* ============================================================\n   INIT\n   ============================================================ */\nrestoreAdminSession(); // GET /api/auth/me \u2014 restores an existing admin session via cookie\n";
